/**
 * DS DescriptionList — PatternFly 6 DescriptionList under the Golden Passport dials.
 * Thin wrapper: the dial CSS (src/styles) already brands it; add DS
 * defaults here when the design system diverges from stock PF6.
 * No ref: PF6's DescriptionList is a plain function component (nothing to forward).
 * Generated by scripts/gen-pf-wrappers.mjs — hand-maintained after that.
 */
import { DescriptionList as PFDescriptionList } from "@patternfly/react-core";
import type { ComponentPropsWithoutRef } from "react";

export type DescriptionListProps = ComponentPropsWithoutRef<typeof PFDescriptionList>;

export function DescriptionList(props: DescriptionListProps) {
  return <PFDescriptionList {...props} />;
}

export {
  DescriptionListDescription,
  DescriptionListGroup,
  DescriptionListTerm,
} from "@patternfly/react-core";
